import threading

def reproduce(connect, service) -> str | None:
    # Household 1 = accounts 1+2. Set combined to 200, then concurrent
    # withdrawals of 150 from different accounts must not both succeed.
    for attempt in range(5):
        with connect() as conn:
            conn.execute("UPDATE accounts SET balance = 100 WHERE id IN (1, 2)")

        barrier = threading.Barrier(2)
        outcomes = []

        def worker(account_id, amount):
            try:
                with connect() as conn:
                    barrier.wait()
                    try:
                        service.withdraw(conn, account_id, amount)
                        outcomes.append("ok")
                    except service.InsufficientFunds:
                        outcomes.append("rejected")
                    except Exception as e:
                        outcomes.append(f"error:{type(e).__name__}")
            except Exception as e:
                try:
                    outcomes.append(f"error:{type(e).__name__}")
                except Exception:
                    pass

        t1 = threading.Thread(target=worker, args=(1, 150))
        t2 = threading.Thread(target=worker, args=(2, 150))
        t1.start()
        t2.start()
        t1.join()
        t2.join()

        with connect() as conn:
            row = conn.execute("SELECT SUM(balance) FROM accounts WHERE household = 1").fetchone()
            combined = row[0] if row else None

        if combined is not None and combined < 0:
            return f"household combined balance negative: {combined} after concurrent withdrawals (both debited, rule requires >= 0)"
        # If both succeeded, that's also a violation even if timing gave combined <0 check above;
        # combined should be -100 in that case, already caught. Reset and retry if race didn't trigger.
        if outcomes.count("ok") == 2:
            # Both passed the combined-balance check -> bug (combined must be -100)
            return "both concurrent household withdrawals succeeded, household overdrawn (combined-balance check bypassed)"
    return None
